data.getstorage#GetStorage:
Toàn bộ kho nông sản (chờ DB). Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:GetStorage(src)
const result = exports.az_farm.GetStorage(src)
src: number — server id người chơi
Trả về: table | nil — { capLevel, maxCapLevel, capacity, maxCapacity, used, minSlots, items, upgrade? }. items = mảng { name, label, category, level, count } (có cả sản phẩm đã mở khoá mà đang có 0). upgrade = { level, amount, materials } của cấp kho kế tiếp (người chơi tự nâng bằng nguyên liệu túi đồ, không khoá theo cấp nghề), không có khi kho đã tối đa. nil khi chưa vào nhân vậtVí dụ
local st = exports.az_farm:GetStorage(src)
if st then print(('kho %d/%d'):format(st.used, st.capacity)) end
const st = await exports.az_farm.GetStorage(src);
if (st) console.log(`kho ${st.used}/${st.capacity}`);

data.getfreespace#GetFreeSpace:
Sức chứa còn trống = capacity - used, không âm (chờ DB). Chưa vào nhân vật → 0. Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:GetFreeSpace(src)
const result = exports.az_farm.GetFreeSpace(src)
src: number — server id người chơi
Trả về: numberVí dụ
if exports.az_farm:GetFreeSpace(src) < 10 then
  exports.az_core:Notify(src, 'Kho nông sản sắp đầy', 'warning')
end
if ((await exports.az_farm.GetFreeSpace(src)) < 10) {
  exports.az_core.Notify(src, 'Kho nông sản sắp đầy', 'warning');
}

data.cancarry#CanCarry:
Kho còn chứa thêm được count món này không (chờ DB, không đổi gì). Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:CanCarry(src, name, count)
const result = exports.az_farm.CanCarry(src, name, count)
src: number — server id người chơi
name: string — tên sản phẩm (cây trồng, sản phẩm vật nuôi, công thức) trong khoá farm, vd lua_mi
count: number — số nguyên ≥ 1
Trả về: boolean, string? — true; false, err với err = not_loaded, invalid_count, invalid_item, not_enough_spaceVí dụ
local ok, err = exports.az_farm:CanCarry(src, 'ngo', 5)
if not ok then return { ok = false, message = err } end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, err] = arr(await exports.az_farm.CanCarry(src, 'ngo', 5));
if (!ok) return { ok: false, message: err };

data.removefarmitem#RemoveFarmItem:
Bớt sản phẩm trong kho (chờ DB). Không đủ thì không bớt gì. Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:RemoveFarmItem(src, name, count)
const result = exports.az_farm.RemoveFarmItem(src, name, count)
src: number — server id người chơi
name: string — tên sản phẩm (cây trồng, sản phẩm vật nuôi, công thức) trong khoá farm, vd lua_mi
count: number — số nguyên ≥ 1
Trả về: boolean, string? — true; false, err với err = not_loaded, invalid_count, not_enough_itemVí dụ
local ok = exports.az_farm:RemoveFarmItem(src, 'lua_mi', 20)
if ok then exports.az_core:AddItem(src, 'bread', 1) end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok] = arr(await exports.az_farm.RemoveFarmItem(src, 'lua_mi', 20));
if (ok) exports.az_core.AddItem(src, 'bread', 1);

data.getfarmstate#GetFarmState:
Cấp nghề & EXP. Trạng thái farm (chờ DB). Chỉ có cấp nghề, tính từ EXP (không trần). Cấp nghề chỉ mở khoá cây trồng / vật nuôi / công thức mới, không tăng kho hay quyền lợi khác. Không ném lỗi: lỗi / chưa vào nhân vật → nil.
local result = exports.az_farm:GetFarmState(src)
const result = exports.az_farm.GetFarmState(src)
src: number — server id người chơi
Trả về: table | nil — { exp, jobLevel, capLevel }: exp = tổng EXP nghề, jobLevel = cấp nghề, capLevel = cấp khoVí dụ
local s = exports.az_farm:GetFarmState(src)
if s then print(('cấp nghề %d, cấp kho %d'):format(s.jobLevel, s.capLevel)) end
const s = await exports.az_farm.GetFarmState(src);
if (s) console.log(`cấp nghề ${s.jobLevel}, cấp kho ${s.capLevel}`);

data.canplant#CanPlant:
Đủ cấp nghề để trồng cây này không (chờ DB). Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:CanPlant(src, name)
const result = exports.az_farm.CanPlant(src, name)
src: number — server id người chơi
name: string — tên cây trồng (khoá farm → Crops)
Trả về: boolean, string?, number? — true; false, err, need với err = not_loaded, invalid_item, job_level_low (need = cấp nghề cần)Ví dụ
local ok, err, need = exports.az_farm:CanPlant(src, 'dau_tay')
if err == 'job_level_low' then
  exports.az_core:Notify(src, ('Cần cấp nghề %d'):format(need), 'error')
end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, err, need] = arr(await exports.az_farm.CanPlant(src, 'dau_tay'));
if (err === 'job_level_low') exports.az_core.Notify(src, 'Cần cấp nghề ' + need, 'error');

data.addfarmexp#AddFarmExp:
Cộng / trừ EXP nghề (chờ DB), không có trần. Lên cấp nghề thì người chơi nhận thông báo, bắn az_farm:expChanged / az_farm:jobLevelUp. Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:AddFarmExp(src, amount)
const result = exports.az_farm.AddFarmExp(src, amount)
src: number — server id người chơi
amount: number — số nguyên, âm = trừ (EXP không xuống dưới 0)
Trả về: number, table? — added, info: added = EXP thực cộng (trừ thì không xuống dưới 0), info = { exp, jobLevel }. Chưa vào nhân vật → chỉ 0Ví dụ
local added, info = exports.az_farm:AddFarmExp(src, 50)
if info then print('cấp nghề', info.jobLevel) end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [added, info] = arr(await exports.az_farm.AddFarmExp(src, 50));
if (info) console.log('cấp nghề', info.jobLevel);

data.setjoblevelbyid#SetJobLevelById:
Đặt thẳng cấp nghề (EXP = mức đầu của cấp đó) như lệnh /farm_setjob (chờ DB). Giới hạn duy nhất là maxLevel của config. Ném lỗi khi DB lỗi / kho bị khoá quá 15s.
local result = exports.az_farm:SetJobLevelById(id, level)
const result = exports.az_farm.SetJobLevelById(id, level)
id: number — id nhân vật (GetPlayer(src).id), người chơi offline cũng được
level: number — cấp nghề, số nguyên ≥ 1. Lớn hơn cấp cao nhất của Levels (maxLevel) thì kẹp về maxLevel
Trả về: boolean, table | string — true, { exp, jobLevel }; false, err với err = invalid_id_card, invalid_level (level không phải số nguyên ≥ 1)Ví dụ
local ok, res = exports.az_farm:SetJobLevelById(charId, 10)
if ok then print('exp mới', res.exp) end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, res] = arr(await exports.az_farm.SetJobLevelById(charId, 10));
if (ok) console.log('exp mới', res.exp);

data.visitfarm#VisitFarm:
Ghé thăm farm bạn bè (như lệnh /ghetham <id>): kiểm 2 người là bạn bè (az_core AreFriends) rồi vào bucket BucketOffset + idCard. Chủ farm offline cũng vào được, chủ đang ở trong farm thì gặp nhau. Vào được thì báo "Chào mừng tới" kèm tên farm. Khách chỉ xem và mua ở quầy hàng, không sửa farm.
local result = exports.az_farm:VisitFarm(src, idCard)
const result = exports.az_farm.VisitFarm(src, idCard)
src: number — server id người chơi
idCard: number — id nhân vật của bạn bè (chủ farm). Là chính mình thì vào farm của mình
Trả về: boolean, string? — true; false, err với err = not_loaded, invalid_id_card, not_friends, hoặc lỗi của EnterFarmVí dụ
local ok, err = exports.az_farm:VisitFarm(src, friendId)
if not ok then exports.az_core:Notify(src, 'Không ghé được: ' .. err, 'error') end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, err] = arr(exports.az_farm.VisitFarm(src, friendId));
if (!ok) exports.az_core.Notify(src, 'Không ghé được: ' + err, 'error');

data.enterfarm#EnterFarm:
Vào / rời farm. Đưa người chơi vào farm: chuyển sang routing bucket BucketOffset + owner, dịch tới điểm trong farm, nhớ chỗ đứng để lúc ra trả về. Không cooldown, không thông báo (NPC vào farm mới có). Không kiểm quyền vào farm người khác: resource gọi tự kiểm. Bắn az_farm:farmEntered.
local result = exports.az_farm:EnterFarm(src, owner)
const result = exports.az_farm.EnterFarm(src, owner)
src: number — server id người chơi
owner?: number — id nhân vật chủ farm. nil = farm của chính mình; truyền giá trị không phải số nguyên dương → invalid_id_card
Trả về: boolean, string? — true; false, err với err = invalid_player, already_inside, invalid_id_card, not_loaded, in_vehicle, other_bucket (đang ở bucket khác 0)Ví dụ
local ok, err = exports.az_farm:EnterFarm(src)
if not ok then exports.az_core:Notify(src, 'Không vào được farm: ' .. err, 'error') end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, err] = arr(exports.az_farm.EnterFarm(src));
if (!ok) exports.az_core.Notify(src, 'Không vào được farm: ' + err, 'error');

data.getfarminside#GetFarmInside:
Người chơi đang ở farm nào. nil khi không ở trong farm.
local result = exports.az_farm:GetFarmInside(src)
const result = exports.az_farm.GetFarmInside(src)
src: number — server id người chơi
Trả về: { owner, bucket } | nilVí dụ
local inside = exports.az_farm:GetFarmInside(src)
if inside then print('đang ở farm của', inside.owner) end
const inside = exports.az_farm.GetFarmInside(src);
if (inside) console.log('đang ở farm của', inside.owner);

data.getfarmviewers#GetFarmViewers:
Server id của mọi người đang ở trong farm của owner (cả chủ farm nếu đang ở trong).
local result = exports.az_farm:GetFarmViewers(owner)
const result = exports.az_farm.GetFarmViewers(owner)
owner: number — id nhân vật chủ farm
Trả về: number[]Ví dụ
for _, s in ipairs(exports.az_farm:GetFarmViewers(owner)) do
  exports.az_core:Notify(s, 'Chủ farm vừa đặt thêm ô đất', 'info')
end
for (const s of exports.az_farm.GetFarmViewers(owner)) {
  exports.az_core.Notify(s, 'Chủ farm vừa đặt thêm ô đất', 'info');
}

data.getinteractconfig#GetInteractConfig:
Prop tương tác. Cấu hình Config.World.Interact đang áp (sửa ở az-tool, trang Cấu hình kỹ thuật → Prop tương tác). Mỗi khoá là 1 tính năng: storage, stall, profile, level, decorShop, decorInventory, leave. Đặt trang trí có tên nằm trong props thì nhìn vào prop bấm G hiện mục của tính năng đó.
local result = exports.az_farm:GetInteractConfig()
const result = exports.az_farm.GetInteractConfig()
Trả về: table — { [feature] = { props, distance, who, label, visitorLabel? } }. who = owner (chủ farm) | visitor (chỉ khách) | allVí dụ
local stall = exports.az_farm:GetInteractConfig().stall
print('prop quầy hàng:', table.concat(stall.props, ', '))
const stall = exports.az_farm.GetInteractConfig().stall;
console.log('prop quầy hàng:', stall.props.join(', '));

data.getplacedprops#GetPlacedProps:
Mọi prop đã đặt trong farm (chờ DB). Không ném lỗi: lỗi / id sai → nil.
local result = exports.az_farm:GetPlacedProps(owner)
const result = exports.az_farm.GetPlacedProps(owner)
owner: number — id nhân vật chủ farm
Trả về: table[] | nil — mảng { id, name, x, y, z, rx, ry, rz, plot } xếp theo id. plot = trạng thái ô đất / máy (chỉ có ở prop loại land / machine)Ví dụ
local props = exports.az_farm:GetPlacedProps(owner) or {}
print(('farm %d có %d prop'):format(owner, #props))
const props = (await exports.az_farm.GetPlacedProps(owner)) || [];
console.log(`farm ${owner} có ${props.length} prop`);

data.getpenanimals#GetPenAnimals:
Danh sách vật nuôi đang nuôi trong một chuồng (tính trạng thái đói / lớn / sẵn sàng thu hoạch tại thời điểm gọi).
local result = exports.az_farm:GetPenAnimals(owner, id)
const result = exports.az_farm.GetPenAnimals(owner, id)
owner: number — id nhân vật chủ farm
id: number — id prop chuồng đã đặt (id trong GetPlacedProps)
Trả về: table[] | nil — mảng { id, kind, label, cycle, status, adult, hungry, dead, full, stock, harvested, boughtAt, growLeft?, hungryLeft?, deathLeft?, nextLeft?, canFeed, canCollect, canSlaughter, product?, productLabel?, yield, meat?, meatLabel?, meatAmount }; nil khi prop không tồn tại hoặc không phải chuồngVí dụ
local animals = exports.az_farm:GetPenAnimals(owner, penId) or {}
print('số con trong chuồng:', #animals)
const animals = exports.az_farm.GetPenAnimals(owner, penId) || [];
console.log('số con trong chuồng:', animals.length);

data.getfarmtutorial#GetFarmTutorial:
Tiến độ hướng dẫn nông trại (9 bước bắt buộc để lên cấp 2: chào NPC, lúa mì, nhà chính, nhà kho, chuồng gà, cho ăn + thu trứng, làm bánh, bán ở chợ, góp thùng đơn tân thủ) của người chơi đang online. Chỉ có khi nhân vật đã vào farm của mình ít nhất 1 lần lúc cấp 1, EXP 0.
local result = exports.az_farm:GetFarmTutorial(src)
const result = exports.az_farm.GetFarmTutorial(src)
src: number — server id người chơi
Trả về: table | nil — { step, total, done, started }: step = bước đang làm (1–9), total = tổng số bước, done = đã xong, started = đã bấm "Bắt đầu hướng dẫn". nil khi chưa có dữ liệuVí dụ
local tut = exports.az_farm:GetFarmTutorial(src)
if tut and not tut.done then print('đang ở bước', tut.step) end
const tut = await exports.az_farm.GetFarmTutorial(src);
if (tut && !tut.done) console.log('đang ở bước', tut.step);

data.getfarmtutorialorder#GetFarmTutorialOrde:
Đơn tân thủ của bước 9 (góp thùng ở xe tải cổng farm). az_core logistics gọi khi mở màn Đơn hàng thành phố để chèn đơn này lên đầu (id 0). Không ném lỗi.
local result = exports.az_farm:GetFarmTutorialOrder(src)
const result = exports.az_farm.GetFarmTutorialOrder(src)
src: number — server id người chơi
Trả về: table | nil — { title, image, crates, stock }: crates = mảng { key, item, label, count, done } (lúa mì, trứng gà), stock = { [item] = số trong kho nông sản }. nil khi người chơi không ở bước 9Ví dụ
local o = exports.az_farm:GetFarmTutorialOrder(src)
if o then print(o.title, #o.crates) end
const o = await exports.az_farm.GetFarmTutorialOrder(src);
if (o) console.log(o.title, o.crates.length);

data.packfarmtutorialcrate#PackFarmTutorialCr:
Góp 1 thùng của đơn tân thủ: kiểm bước 9, đứng gần xe tải (Pack.Distance + 3 m), trừ hàng trong kho nông sản rồi tick bước. Góp đủ thùng thì xong hướng dẫn. Không ném lỗi.
local result = exports.az_farm:PackFarmTutorialCrate(src, item)
const result = exports.az_farm.PackFarmTutorialCrate(src, item)
src: number — server id người chơi
item: string — sản phẩm của thùng (crates[].item từ GetFarmTutorialOrder)
Trả về: boolean, string? — true khi góp được; false, message với message là câu báo lỗi tiếng Việt đã dịch (thiếu hàng, quá xa, thùng đã góp, không ở bước 9)Ví dụ
local ok, msg = exports.az_farm:PackFarmTutorialCrate(src, 'trung_ga')
if not ok then exports.az_core:Notify(src, msg, 'error') end
const arr = (r) => (Array.isArray(r) ? r : [r]);
const [ok, msg] = arr(await exports.az_farm.PackFarmTutorialCrate(src, 'trung_ga'));
if (!ok) exports.az_core.Notify(src, msg, 'error');

data.getfarmdata#GetFarmData:
Cấu hình. Toàn bộ dữ liệu khoá farm đã chuẩn hoá (bản đang áp, đổi ngay khi sửa trên az-tool). Bảng lớn: gọi 1 lần rồi giữ, đừng gọi mỗi tick.
local result = exports.az_farm:GetFarmData()
const result = exports.az_farm.GetFarmData()
Trả về: table — { settings, items, crops, cropList, trees, animals, animalList, pets, petList, decors, decorList, machines, machineList, recipes, recipeList, products, levels, levelRewards, maxLevel, capacityLevels }. crops / animals / recipes chỉ gồm mục đang bật; trees là bảng các cây ăn quả lâu năm trong decors (category = "plant" có chọn crop). settings có landMax (trần ô đất); số ô đất tặng theo levels[].land (cấp 1 = lúc mới vào); quà từng cấp ở levelRewards[cấp] = mảng { kind = "money" | "gem" | "item" | "decor", name?, count }Ví dụ
local data = exports.az_farm:GetFarmData()
for _, c in ipairs(data.cropList) do print(c.name, c.label, c.level) end
const data = exports.az_farm.GetFarmData();
for (const c of data.cropList) console.log(c.name, c.label, c.level);

data.getcrop#GetCrop:
Định nghĩa 1 cây trồng ngắn ngày đang bật (gieo trên ô đất; cây ăn quả lâu năm cấu hình ở Decors loại plant và xem qua GetDecor / GetFarmData().trees).
local result = exports.az_farm:GetCrop(name)
const result = exports.az_farm.GetCrop(name)
name: string — tên cây trồng trên ô đất
Trả về: table | nil — { name, label, type, category, level, growTime, yields, exp, fertilizeGem?, description, image, enabled, sortOrder }. type = "crop", growTime = giâyVí dụ
local c = exports.az_farm:GetCrop('lua_mi')
if c then print(c.label, c.growTime) end
const c = exports.az_farm.GetCrop('lua_mi');
if (c) console.log(c.label, c.growTime);

data.getproduct#GetProduct:
Định nghĩa 1 sản phẩm (thứ nằm trong kho nông sản).
local result = exports.az_farm:GetProduct(name)
const result = exports.az_farm.GetProduct(name)
name: string — tên sản phẩm (cây trồng, sản phẩm vật nuôi, công thức) trong khoá farm, vd lua_mi
Trả về: table | nil — { label, category, image, description, priceMin, priceMax, playerMin, playerMax, source, level }. priceMin/priceMax = giá NPC thu mua (Items.npcMin/npcMax), playerMin/playerMax = khung giá quầy người chơi (Items.playerMin/playerMax); chưa có giá thì = 0. category = farm | food | material, source = crop | tree | animal | recipe | supply | itemVí dụ
local p = exports.az_farm:GetProduct('ngo')
local label = p and p.label or 'ngo'
const p = exports.az_farm.GetProduct('ngo');
const label = p ? p.label : 'ngo';

data.getworldconfig#GetWorldConfig:
Cấu hình kỹ thuật đang áp (Config.World, khoá farmWorld): Storage, Level, Instance, Decor, Crop, Machine, Market, Interact, Profile.
local result = exports.az_farm:GetWorldConfig()
const result = exports.az_farm.GetWorldConfig()
Trả về: tableVí dụ
local exit = exports.az_farm:GetWorldConfig().Instance.ExitCoords
