data.triggerservercallback#TriggerServerCallb:
Gọi callback server, chờ kết quả.
local result = exports.az_core:TriggerServerCallback(name, ...args)
const result = await exports.az_core.TriggerServerCallback(name, ...args)
name: string
...args: any — dữ liệu gửi lên — server phải kiểm lại
Trả về: Promise → any — giá trị handler server trả. Lỗi / quá 15 giây / tên không tồn tại → lỗi (reject)Ví dụ
CreateThread(function()
  local ok, res = pcall(function()
    return exports.az_core:TriggerServerCallback('myres:buy', 'water', 2)
  end)
  if not ok or not res then return exports.az_core:Notify('Máy chủ không phản hồi', 'error') end
  if not res.ok then return exports.az_core:Notify(res.message, 'error') end
  exports.az_core:Notify('Đã mua', 'success')
end)
try {
  const res = await exports.az_core.TriggerServerCallback('myres:buy', 'water', 2);
  if (!res.ok) return exports.az_core.Notify(res.message, 'error');
  exports.az_core.Notify('Đã mua', 'success');
} catch {
  exports.az_core.Notify('Máy chủ không phản hồi', 'error');
}

data.registernuicallback#RegisterNuiCallback:
Nhận callback NUI từ khung az_core thay cho RegisterNUICallback của resource mình. Đăng ký lại cùng tên thì thay handler. Resource dừng thì callback trả { ok = false } tới khi đăng ký lại. az_core chạy lại thì phải đăng ký lại.
local result = exports.az_core:RegisterNuiCallback(name, handler)
const result = exports.az_core.RegisterNuiCallback(name, handler)
name: string — tên fetchNui(name) gọi từ khung az_core
handler: function — nhận data, trả bảng kết quả cho NUI (được async). Trả nil = { ok = true }
Trả về: boolean — false khi tên trống, handler không phải hàm, hoặc tên trùng callback có sẵn của coreVí dụ
exports.az_core:RegisterNuiCallback('shop:buy', function(data)
  return { ok = true }
end)
exports.az_core.RegisterNuiCallback('shop:buy', async (data) => {
  const res = await exports.az_core.TriggerServerCallback('shop:buy', data.item, data.qty);
  return res ?? { ok: false };
});

data.registercallback#RegisterCallback:
Đăng ký callback. Trùng tên → ghi đè (core log cảnh báo). Resource đăng ký bị stop thì callback của nó tự gỡ.
exports.az_core:RegisterCallback(name, handler)
exports.az_core.RegisterCallback(name, handler)
name: string — đặt dạng resource:viec
handler: function(src, ...args) — giá trị return được gửi về client; được là async
Restart az_core thì callback mất. Đăng ký lại trong onResourceStart khi res == 'az_core' — xem Dùng core từ resource khác.
Ví dụ
exports.az_core:RegisterCallback('myres:buy', function(src, itemName, count)
  count = math.floor(tonumber(count) or 0)          -- không tin client
  if count < 1 or count > 10 then return { ok = false, message = 'Số lượng sai' } end
  if not exports.az_core:RemoveMoney(src, 'cash', 50 * count, 'myres:buy') then
    return { ok = false, message = 'Không đủ tiền' }
  end
  exports.az_core:AddItem(src, itemName, count)
  return { ok = true }
end)
exports.az_core.RegisterCallback('myres:buy', async (src, itemName, count) => {
  count = Math.floor(Number(count));
  if (!(count >= 1 && count <= 10)) return { ok: false, message: 'Số lượng sai' };
  if (!exports.az_core.RemoveMoney(src, 'cash', 50 * count, 'myres:buy')) return { ok: false, message: 'Không đủ tiền' };
  exports.az_core.AddItem(src, itemName, count);
  return { ok: true };
});

data.registerremoteconfig#RegisterRemoteConfi:
Cho resource khác dùng cấu hình sửa được từ az-tool (/gm) như module trong core. Đăng ký xong core đọc DB rồi gọi apply ngay; GM lưu bản mới thì apply được gọi lại.
local result = exports.az_core:RegisterRemoteConfig(name, defaults, apply, validate)
const result = await exports.az_core.RegisterRemoteConfig(name, defaults, apply, validate)
name: string — khoá trong bảng az_config (cũng là tên trang trong az-tool / /gm)
defaults: table — cấu hình mặc định khi DB chưa có
apply: function(cfg) — áp cấu hình; trả mảng chuỗi cảnh báo (có thể rỗng)
validate?: function(cfg) — trả { errors, warnings } (mảng chuỗi). Có errors thì không lưu / không áp
Trả về: Promise → { source, warnings, errors }
Resource bị stop thì cấu hình tự gỡ. Restart az_core thì phải đăng ký lại (mẫu: src/addons/lib/core.js onCore).
Ví dụ
exports.az_core:RegisterRemoteConfig('myres', { Price = 100 }, function(cfg)
  Price = tonumber(cfg.Price) or 100
  return {}
end, function(cfg)
  if (tonumber(cfg.Price) or 0) <= 0 then return { errors = { 'Price phải > 0' }, warnings = {} } end
  return { errors = {}, warnings = {} }
end)
await exports.az_core.RegisterRemoteConfig('myres', { Price: 100 }, (cfg) => {
  price = Number(cfg.Price) || 100;
  return [];
}, (cfg) => (Number(cfg.Price) > 0 ? { errors: [], warnings: [] } : { errors: ['Price phải > 0'], warnings: [] }));

data.registercommand#RegisterCommand:
Lệnh chat có kiểm quyền và gợi ý lệnh. Resource đăng ký bị stop thì lệnh của nó tự gỡ.
exports.az_core:RegisterCommand(name, group, handler, opts)
exports.az_core.RegisterCommand(name, group, handler, opts)
name: string — không có dấu /
group: string — quyền tối thiểu: user, mod, admin, superadmin
handler: function(ctx) — ctx: src, args (mảng chuỗi), raw, reply(msg), isConsole
opts?: table — help, params ([{ name, help }]), allowConsole (mặc định true)
Ví dụ
exports.az_core:RegisterCommand('givewater', 'admin', function(ctx)
  local target = tonumber(ctx.args[1])
  if not target then return ctx.reply('Dùng: /givewater [id]') end
  exports.az_core:AddItem(target, 'water', 1)
  ctx.reply('Đã đưa nước')
end, { help = 'Đưa nước', params = { { name = 'id', help = 'server id' } } })
exports.az_core.RegisterCommand('givewater', 'admin', (ctx) => {
  const target = Number(ctx.args[0]);
  if (!target) return ctx.reply('Dùng: /givewater [id]');
  exports.az_core.AddItem(target, 'water', 1);
  ctx.reply('Đã đưa nước');
}, { help: 'Đưa nước', params: [{ name: 'id', help: 'server id' }] });

