const result = exports.az_core.KeyPress(key, description, time, inVehicle, coords, label)
key: string — vd E
description: string
time?: number — ms phải giữ phím; 0 = bấm nhanh
inVehicle?: boolean
coords?: vector3 | table — nút bám theo toạ độ; bỏ trống = giữa màn hình
label?: string — chữ trên nút
Trả về: boolean | Promise<boolean>Ví dụ
local shop = vector3(25.7, -1347.3, 29.5)
CreateThread(function()
  while true do
    local sleep = 500
    if #(GetEntityCoords(PlayerPedId()) - shop) < 2.0 then
      sleep = 0
      if exports.az_core:KeyPress('E', 'Mở cửa hàng', 0, false, shop) then
        TriggerServerEvent('myres:openShop')
      end
    end
    Wait(sleep)
  end
end)
const shop = { x: 25.7, y: -1347.3, z: 29.5 };
setTick(() => {
  const [x, y, z] = GetEntityCoords(PlayerPedId(), false);
  if (Math.hypot(x - shop.x, y - shop.y, z - shop.z) > 2) return;
  if (exports.az_core.KeyPress('E', 'Mở cửa hàng', 0, false, shop)) emitNet('myres:openShop');
});

