data.1-tạo-hoá-đơn-luôn-về-go-bank#1. Tạo hoá:
Không trừ thẳng tiền ngân hàng cho các khoản phạt / dịch vụ và không tạo bảng hoá đơn riêng. Mọi hoá đơn đều tạo qua GO Bank để người chơi tự trả trên app, bật tự động trừ (autopay), hoặc trả tiền mặt tại quầy.
const phoneMoney = require('../../phone/money');
const out = await phoneMoney.createBill({
  idCard: player.id,                                     // az_users.id (không phải source)
  issuer: 'Bệnh viện Pillbox',
  title: 'Viện phí cấp cứu',
  amount: fee,
  ref: `job:ambulance:admit:${player.id}:${Date.now()}`, // trùng ref sẽ trả duplicate
  resource: 'mp_ambulance',                              // phải có trong Boss.bills nếu cộng quỹ ngành
}).catch((err) => ({ success: false, error: err.message }));
local out = exports.az_core:CreateBill(src, {
  amount = 1200,
  issuer = 'Công an',
  title = 'Biên bản phạt',
  ref = ('job:police:fine:%d:%d'):format(idCard, fineId),
})
Khi hoá đơn được trả (trên app, autopay hay tiền mặt ở quầy), core bắn event local server az_core:phone:billPaid kèm thông tin hoá đơn (id, idCard, amount, ref, resource, auto, cash).
Các ngành quản lý trong core tự cộng quỹ từ Boss.bills (shared/jobs/<job>.js); các resource tự giữ quỹ (mp_police, mp_ambulance) nghe az_core:phone:billPaid và đối soát định kỳ bảng gtago_bank_bill (status = 1).

data.server#Server:
const Callbacks = require('../../lib/callbacks');
const Cooldown = require('../../lib/cooldown');
const Job = require('../../lib/job');
const { playerDist } = require('../../lib/geo');
const { Feature } = require('@shared/feature');
class JobsMechanicRepair extends Feature {
  #cd = null;
  constructor() {
    super('jobs:mechanic:repair');
  }
  #repair(src, target) {
    const j = Job.check(src, 'mechanic', { onDuty: true });
    if (!j.ok) return { ok: false, message: j.message };
    if (this.#cd.hit(src)) return { ok: false, message: 'Thao tác quá nhanh' };
    if (playerDist(src, target) > 3) return { ok: false, message: 'Đứng gần hơn' };
    // ...
    return { ok: true, message: 'Đã sửa xong' };
  }
  setup() {
    this.#cd = Cooldown.create(1500);
    Callbacks.register('mechanic:repair', (src, target) => this.#repair(src, target));
  }
}
module.exports = new JobsMechanicRepair();

