  SetNuiFocus(false, false);
  return true;
});
Nui.onReady(({ reload }) => {
  // NUI vừa load / reload: đẩy lại state (phải idempotent)
});
import { fetchNui, useNuiEvent } from '../nui';
export default function XyzApp() {
  const [data, setData] = useState<{ title: string } | null>(null);
  useNuiEvent<{ title: string }>('xyz:open', setData);
  if (!data) return null;
  return <button onClick={() => { setData(null); fetchNui('xyz:close'); }}>{data.title}</button>;
}
Message của điện thoại / GO Bank có cờ phone: true / bank: true. useNuiEvent bỏ qua các message này vì chúng có listener riêng.
