data.server-đăng-ký-callback-dùng-export-nghe:
local AZ = exports.az_core
-- client gọi: TriggerServerCallback('myres:buyWater')
AZ:RegisterCallback('myres:buyWater', function(src)
  -- không tin client: giá, số lượng do server quyết định
  if not AZ:CanCarryItem(src, 'water', 1) then
    return { ok = false, message = 'Túi đầy' }
  end
  if not AZ:RemoveMoney(src, 'cash', 50, 'myres:buyWater') then
    return { ok = false, message = 'Không đủ tiền mặt' }
  end
  AZ:AddItem(src, 'water', 1)
  return { ok = true, message = 'Đã mua nước' }
end)
-- export async (trả Promise) gọi trong handler / thread là tự chờ
AZ:RegisterCallback('myres:myCars', function(src)
  return AZ:GetVehicles(src)
end)
AddEventHandler('az_core:playerLoaded', function(src, data)
  print(('%s vào game, job %s'):format(data.charName, data.job.name))
end)
AddEventHandler('az_core:jobChanged', function(src, job, oldJob)
  if job.name == 'police' and job.onDuty then
    AZ:Notify(src, 'Đã vào ca', 'success')
  end
end)
const AZ = exports.az_core;
AZ.RegisterCallback('myres:buyWater', (src) => {
  if (!AZ.CanCarryItem(src, 'water', 1)) return { ok: false, message: 'Túi đầy' };
  if (!AZ.RemoveMoney(src, 'cash', 50, 'myres:buyWater')) return { ok: false, message: 'Không đủ tiền mặt' };
  AZ.AddItem(src, 'water', 1);
  return { ok: true, message: 'Đã mua nước' };
});
