data.đăng-ký-lại-khi-az_core-restart#Đăng ký:
Callback, item dùng được, mục menu tròn... resource bạn đăng ký vào core nằm trong bộ nhớ core. Restart az_core là mất, phải đăng ký lại.
local function registerAll()
  exports.az_core:RegisterCallback('myres:buyWater', buyWater)
  exports.az_core:RegisterUsableItem('water', function(src, item) end)
end
CreateThread(registerAll)                                   -- lúc resource mình start
AddEventHandler('onResourceStart', function(res)
  if res == 'az_core' then registerAll() end                -- lúc core restart
end)
function registerAll() {
  exports.az_core.RegisterCallback('myres:buyWater', buyWater);
  exports.az_core.RegisterUsableItem('water', (src, item) => {});
}
setImmediate(registerAll);
on('onResourceStart', (res) => { if (res === 'az_core') registerAll(); });
Phía client, mục menu tròn đăng ký lại trong event az_core:radial:ready. Đăng ký trùng tên callback chỉ ghi đè (core log cảnh báo), không lỗi.

data.viết-hàm-trong-class-đăng-ký-trong-setup:
const { Feature } = require('@shared/feature');
const PlayerManager = require('../player/PlayerManager');
const DB = require('../../lib/database');
class Vidu extends Feature {
  #points = new Map(); // src -> điểm
  constructor() {
    super('vidu', { deps: [PlayerManager] });
  }
  setup() {
    // webpack: phải dùng global.exports, KHÔNG viết exports(...)
    global.exports('GetPoints', this.getPoints);
    global.exports('AddPoints', this.addPoints);
  }
  async init() {
    // nạp DB 1 lần. Method async public tự chờ init() xong rồi mới chạy
  }
  getPoints(src) {
    return this.#points.get(Number(src)) || 0;
  }
  async addPoints(src, amount, reason) {
    src = Number(src);
    amount = Math.floor(Number(amount));
    if (!PlayerManager.get(src) || !(amount > 0)) return false; // kiểm đầu vào
    this.#points.set(src, this.getPoints(src) + amount);
    await DB.update('UPDATE az_vidu SET points = points + ? WHERE char_id = ?', [amount, PlayerManager.get(src).id]);
    return true;
  }
}
module.exports = new Vidu();
const { Feature } = require('@shared/feature');
const PlayerData = require('../playerData');
class Vidu extends Feature {
  constructor() {
    super('client:vidu');
  }
  setup() {
    // client: globalThis.exports
    globalThis.exports('IsVip', this.isVip);
  }
  isVip() {
    return (PlayerData.get()?.metadata?.vip || 0) > 0;
  }
}
module.exports = new Vidu();
Feature tự bind mọi method public, nên truyền thẳng this.getPoints vào global.exports được, không mất this.
